import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef{  
    static long pre[];
    static int[] a;
    static int n;
    public static long score(int A, int B){
        return 2L * pre[A] + pre[A+2*B] + 3L * pre[3*n-2 * A-B];
    }
	public static void main (String[] args) throws java.lang.Exception
	{
        FastScanner sc = new FastScanner();
        int t = sc.nextInt();
        StringBuilder out = new StringBuilder();
        while(t-->0){
            n = sc.nextInt();
            a = new int[n*3];
            for(int i=0;i<3*n;i++) a[i] = sc.nextInt();
            Arrays.sort(a);
            for(int l=0,r=a.length-1;l<r;l++,r--){
                int temp = a[l];
                a[l] = a[r];
                a[r] = temp;
            }
            pre = new long[3*n+1];
            for(int i=0;i<3*n;i++){
                pre[i+1] = pre[i] + a[i];
            }
            int B = n;
            long ans = 0;
            for(int A=0;A<=n;A++){
                B = Math.min(B, n-A);
                while(B>0 && score(A, B-1)>=score(A,B)){
                    B--;
                }
                ans = Math.max(ans, score(A, B));
            }
            out.append(ans).append("\n");
        }
        System.out.print(out);
	}
	static class FastScanner{
	    private final InputStream in = System.in;
	    private final byte[] buffer = new byte[1<<16];
	    private int ptr = 0, len = 0;
	    private int read() throws IOException{
	        if(ptr>=len){
	            len = in.read(buffer);
	            ptr = 0;
	             if(len<=0) return -1;
	        }
	        return buffer[ptr++];
	    }
	    
	    int nextInt() throws IOException{
	        int c;
	        do{
	            c = read();
	        } while(c<=' ');
	        int sign = 1;
	        if(c=='-'){
	            sign = -1;
	            c = read();
	        }
	        int num = 0;
	        while(c>' '){
	            num = num * 10 + (c-'0');
	            c = read();
	        }
	        return num * sign;
	    }
	}
}
